const { createClient } = window.supabase;
import { SUPABASE_PUBLISHABLE_KEY, SUPABASE_URL } from "./config.js";

const app = document.querySelector("#app");
const ready = Boolean(SUPABASE_URL && SUPABASE_PUBLISHABLE_KEY);
const supabase = ready ? createClient(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY) : null;
let session = null;
let cases = [], appointments = [], calls = [], analyses = [], documents = [], mailbox = [];
let page = "home", notice = "", visitor = null, cameraPerson = null, mailboxView = "inbox", mailArrivalTimer = null, mailArrivalTimeout = null, autoReplyTimer = null, autoReplyBusy = false;
let cameraState = JSON.parse(localStorage.getItem("pde-camera-state") || "null") || {Portail:true,Hall:true,"Couloir nord":true,Archives:true};
const esc = s => String(s ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const dateLabel = d => d ? new Intl.DateTimeFormat("fr-FR",{day:"2-digit",month:"short",year:"numeric"}).format(new Date(d)) : "Date non précisée";
const dateTimeLabel = d => d ? new Intl.DateTimeFormat("fr-FR",{weekday:"short",day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit"}).format(new Date(d)) : "Date à préciser";
const statusLabel = s => ({open:"En cours",review:"À analyser",closed:"Terminé"}[s] || s);
const caseOptions = selected => `<option value="">Aucun dossier lié</option>${cases.map(c=>`<option value="${c.id}" ${selected===c.id?"selected":""}>${esc(c.case_number)} · ${esc(c.title)}</option>`).join("")}`;
const localDateTime = value => value ? new Date(new Date(value).getTime()-new Date(value).getTimezoneOffset()*60000).toISOString().slice(0,16) : "";

function render(){
  if(!ready)return renderSetup(); if(!session)return renderLogin();
  const active=cases.filter(c=>c.status!=="closed"), closed=cases.filter(c=>c.status==="closed");
  app.innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><span class="brand-mark">P</span><div><b>P.D.E.</b><small>Palais des Enquêtes</small></div></div><nav>
    ${navItem("home","⌂","Accueil")}${navItem("cases","▤","Dossiers")}${navItem("appointments","◷","Rendez-vous")}${navItem("calls","☎","Appels")}${navItem("mailbox","✉","Messagerie")}${navItem("analyses","⚗","Laboratoire")}${navItem("documents","▧","Documents")}${navItem("intercom","⌁","Interphone")}${navItem("cameras","◉","Caméras")}${navItem("archives","▣","Archives")}
    </nav><div class="sidebar-bottom"><div class="identity"><span class="avatar">CL</span><div><b>Camille Lou</b><small>Directrice</small></div></div><button class="text-button" id="signout">Se déconnecter</button></div></aside>
    <section class="workspace"><header class="topbar"><span>ESPACE DE DIRECTION</span><span class="cloud-state"><i></i> Sauvegarde en ligne activée</span></header><div class="content">${notice?`<div class="notice">${esc(notice)}<button id="close-notice" aria-label="Fermer">×</button></div>`:""}${pageContent(active,closed)}</div></section></div>`;
  bind();
}
function navItem(id,icon,label){return `<button class="nav-item ${page===id?"selected":""}" data-page="${id}"><span>${icon}</span>${label}</button>`;}
function renderSetup(){app.innerHTML=`<section class="setup-screen"><div class="setup-card"><div class="brand centered"><span class="brand-mark">P</span><div><b>P.D.E.</b><small>Palais des Enquêtes</small></div></div><p class="eyebrow">BIENVENUE AU BUREAU</p><h1>Préparons ton espace sécurisé.</h1><p class="muted">La connexion au cloud n’est pas encore configurée. Tes dossiers seront synchronisés après le branchement à Supabase.</p></div></section>`;}
function renderLogin(){app.innerHTML=`<section class="login-screen"><form class="login-card" id="login-form"><div class="brand centered"><span class="brand-mark">P</span><div><b>P.D.E.</b><small>Palais des Enquêtes</small></div></div><p class="eyebrow">ESPACE DE DIRECTION</p><h1>Ravie de vous revoir, Camille.</h1><p class="muted">Connecte-toi pour retrouver les dossiers du bureau.</p><label>Adresse e-mail<input name="email" type="email" autocomplete="username" required></label><label>Mot de passe<input name="password" type="password" autocomplete="current-password" required></label><button class="primary full">Se connecter</button><p class="login-note">Connexion privée · données synchronisées</p>${notice?`<p class="error">${esc(notice)}</p>`:""}</form></section>`;document.querySelector("#login-form").addEventListener("submit",login);}
function pageContent(active,closed){
  if(page==="cases"||page==="archives")return casesPage(page==="archives"?closed:active,page==="archives");
  if(page==="appointments")return appointmentsPage();
  if(page==="calls")return callsPage();
  if(page==="mailbox")return mailboxPage();
  if(page==="analyses")return analysesPage();
  if(page==="documents")return documentsPage();
  if(page==="intercom")return intercomPage();
  if(page==="cameras")return camerasPage();
  const now=new Date();const todays=appointments.filter(a=>new Date(a.starts_at).toDateString()===now.toDateString()&&a.status==="planned");const next=appointments.filter(a=>a.status==="planned"&&new Date(a.starts_at)>=now).sort((a,b)=>new Date(a.starts_at)-new Date(b.starts_at))[0];
  return `<p class="eyebrow">ESPACE DE DIRECTION · 11 NOVEMBRE</p><h1>Bonjour, Camille</h1><p class="muted intro">Le bureau du Palais des Enquêtes est à toi.</p><div class="stats"><article><span>DOSSIERS ACTIFS</span><strong>${String(active.length).padStart(2,"0")}</strong><small>Enquêtes en cours</small></article><article><span>RENDEZ-VOUS DU JOUR</span><strong>${String(todays.length).padStart(2,"0")}</strong><small>À recevoir aujourd’hui</small></article><article class="highlight"><span>ANALYSES À SUIVRE</span><strong>${String(analyses.filter(a=>a.status!=="complete").length).padStart(2,"0")}</strong><small>Au laboratoire</small></article></div><div class="dashboard-grid"><section><div class="section-heading"><h2>Dossiers à suivre</h2><button class="text-button" data-page="cases">Voir tous →</button></div>${active.length?`<div class="case-list">${active.slice(0,4).map(caseRow).join("")}</div>`:`<div class="empty-card compact"><p>Aucun dossier en cours.</p><button class="primary" id="new-case-top">Créer un dossier</button></div>`}</section><aside class="next-appointment"><p class="eyebrow">PROCHAIN RENDEZ-VOUS</p>${next?`<h2>${esc(next.title)}</h2><p>${dateTimeLabel(next.starts_at)}</p><small>${esc(next.contact||"Contact à préciser")}</small><button class="secondary small" data-appointment="${next.id}">Ouvrir la fiche</button>`:`<h2>Agenda libre</h2><p>Ajoute un entretien ou un rappel à ton agenda.</p><button class="primary" id="new-appointment-home">＋ Ajouter un rendez-vous</button>`}</aside></div><div class="handover"><span>✦</span><p><b>Reprise de direction</b><br/>Camille Lou est la directrice actuelle. Les notes antérieures à sa reprise restent consultables dans les dossiers.</p></div>`;
}
function casesPage(list,archived){return `<div class="page-title-row"><div><p class="eyebrow">${archived?"HISTORIQUE":"SUIVI DES ENQUÊTES"}</p><h1>${archived?"Archives":"Dossiers"}</h1><p class="muted">${list.length} dossier${list.length===1?"":"s"} · ouvre une fiche pour lire les notes et ajouter une avancée</p></div>${!archived?`<button class="primary" id="new-case">＋ Nouveau dossier</button>`:""}</div>${list.length?`<div class="case-list">${list.map(caseRow).join("")}</div>`:`<div class="empty-card"><div class="empty-icon">▤</div><h2>${archived?"Aucun dossier terminé":"Aucune enquête en cours"}</h2><p>${archived?"Les dossiers terminés apparaîtront ici.":"Crée un dossier pour commencer à consigner l’enquête."}</p>${!archived?`<button class="primary" id="new-case-empty">Créer un dossier</button>`:""}</div>`}`;}
function caseRow(c){return `<button class="case-row" data-open="${c.id}"><span class="case-dot ${esc(c.status)}"></span><span class="case-info"><b>${esc(c.case_number||"PDE-…")} · ${esc(c.title)}</b><small>${esc(c.people||"Personnes à préciser")} · Mis à jour ${dateLabel(c.updated_at)}</small></span><span class="status ${esc(c.status)}">${statusLabel(c.status)}</span><span class="chevron">›</span></button>`;}
function recordHeader(eyebrow,title,count,buttonId,buttonText){return `<div class="page-title-row"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="muted">${count}</p></div><button class="primary" id="${buttonId}">＋ ${buttonText}</button></div>`;}
function appointmentsPage(){const items=[...appointments].sort((a,b)=>new Date(a.starts_at)-new Date(b.starts_at));return `${recordHeader("ORGANISATION","Rendez-vous",`${items.length} rendez-vous enregistrés`,"new-appointment","Nouveau rendez-vous")}${items.length?`<div class="record-list">${items.map(a=>`<button class="record-row" data-appointment="${a.id}"><span class="record-date">${new Intl.DateTimeFormat("fr-FR",{day:"2-digit",month:"short"}).format(new Date(a.starts_at))}<b>${new Intl.DateTimeFormat("fr-FR",{hour:"2-digit",minute:"2-digit"}).format(new Date(a.starts_at))}</b></span><span class="record-main"><b>${esc(a.title)}</b><small>${esc(a.contact||"Contact à préciser")} · ${esc(a.kind)}${a.location?` · ${esc(a.location)}`:""}</small></span><span class="status ${a.status==="completed"?"closed":""}">${a.status==="completed"?"Terminé":a.status==="cancelled"?"Annulé":"Prévu"}</span><span class="chevron">›</span></button>`).join("")}</div>`:`<div class="empty-card"><div class="empty-icon">◷</div><h2>Ton agenda du P.D.E.</h2><p>Crée un rendez-vous et ajoute le compte rendu après l’entretien. Tout sera conservé ici.</p><button class="primary" id="new-appointment-empty">Ajouter un rendez-vous</button></div>`}`;}
function callsPage(){return `${recordHeader("JOURNAL DU BUREAU","Appels",`${calls.length} appels consignés`,"new-call","Consigner un appel")}<div class="call-actions"><button class="secondary" id="simulate-incoming">☎ Simuler un appel entrant</button><p class="sim-note">Les appels simulés sont joués dans l’application ; ils ne composent pas un vrai numéro.</p></div>${calls.length?`<div class="record-list">${[...calls].sort((a,b)=>new Date(b.occurred_at)-new Date(a.occurred_at)).map(c=>`<button class="record-row" data-call="${c.id}"><span class="record-icon">${c.direction==="inbound"?"↙":"↗"}</span><span class="record-main"><b>${esc(c.contact)} · ${c.direction==="inbound"?"Appel entrant":"Appel sortant"}</b><small>${dateTimeLabel(c.occurred_at)}${c.phone?` · ${esc(c.phone)}`:""} ${c.case_id?`· ${esc(caseById(c.case_id)?.title||"")}`:""}</small></span><span class="chevron">›</span></button>`).join("")}</div>`:`<div class="empty-card"><h2>Le journal d’appels est vide</h2><p>Consigne un échange téléphonique ou joue un appel entrant pour commencer l’historique.</p></div>`}`;}
function mailboxPage(){const sent=mailboxView==="sent",items=mailbox.filter(m=>sent?m.direction==="outbound":m.direction==="inbound");return `<div class="page-title-row"><div><p class="eyebrow">CORRESPONDANCE DU PALAIS</p><h1>Messagerie</h1><p class="muted">Échanges de jeu liés aux dossiers · synchronisés dans le cloud</p></div><button class="primary" id="compose-mail">＋ Rédiger</button></div><div class="mail-simulation"><b>Boîte de jeu du P.D.E.</b><span>Les personnages peuvent écrire pendant que tu es connectée. Les messages sont fictifs et ne partent pas vers une vraie boîte e-mail.</span></div><div class="mail-toolbar"><div class="mail-tabs"><button class="${!sent?"active":""}" data-mail-view="inbox">Réception${mailbox.filter(m=>m.direction==="inbound").length?` · ${mailbox.filter(m=>m.direction==="inbound").length}`:""}</button><button class="${sent?"active":""}" data-mail-view="sent">Envoyés</button></div></div>${items.length?`<div class="record-list">${[...items].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)).map(m=>{const answered=mailbox.some(x=>x.direction==="inbound"&&x.reply_to===m.id);const replyInfo=sent&&m.reply_delay_minutes?(answered?"Réponse reçue":`Réponse prévue · ${delayLabel(Number(m.reply_delay_minutes))}`):"";return `<button class="record-row" data-mail="${m.id}"><span class="record-icon">${sent?"↗":"✉"}</span><span class="record-main"><b>${esc(sent?`À : ${m.recipient}`:m.sender_name)} · ${esc(m.subject||"(sans objet)")}</b><small>${dateTimeLabel(m.created_at)} · ${esc(caseById(m.case_id)?.case_number||"Correspondance du bureau")}${replyInfo?` · ${replyInfo}`:""} · ${esc((m.body||"").replace(/\s+/g," ").slice(0,120))}</small></span><span class="chevron">›</span></button>`;}).join("")}</div>`:`<div class="empty-card"><div class="empty-icon">✉</div><h2>${sent?"Aucun message envoyé":"Ta réception est vide"}</h2><p>${sent?"Les messages que tu rédigeras apparaîtront ici.":"Un courrier de jeu arrivera automatiquement pendant que le bureau est ouvert."}</p>${sent?`<button class="primary" id="compose-mail-empty">Rédiger un message</button>`:""}</div>`}`;}
function analysesPage(){return `${recordHeader("LABORATOIRE DU PALAIS","Analyses",`${analyses.length} demandes · ${analyses.filter(a=>a.status!=="complete").length} à suivre`,"new-analysis","Demander une analyse")}${analyses.length?`<div class="record-list">${[...analyses].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)).map(a=>`<button class="record-row" data-analysis="${a.id}"><span class="record-icon">⚗</span><span class="record-main"><b>${esc(a.evidence)}</b><small>${esc(caseById(a.case_id)?.title||"Dossier non lié")} · ${esc(a.requested_by||"Demandeur à préciser")}</small></span><span class="status ${a.status==="complete"?"closed":a.status==="in_progress"?"review":""}">${analysisStatus(a.status)}</span><span class="chevron">›</span></button>`).join("")}</div>`:`<div class="empty-card"><div class="empty-icon">⚗</div><h2>Aucune analyse enregistrée</h2><p>Crée une demande, indique l’autorisation, puis ajoute le résultat quand le laboratoire a terminé.</p><button class="primary" id="new-analysis-empty">Demander une analyse</button></div>`}`;}
function analysisStatus(s){return ({requested:"Demandée",in_progress:"En analyse",complete:"Résultat reçu"}[s]||s);}
function documentsPage(){return `${recordHeader("SECRÉTARIAT","Documents",`${documents.length} documents · brouillons et signatures`,"new-document","Nouveau document")}${documents.length?`<div class="record-list">${[...documents].sort((a,b)=>new Date(b.updated_at)-new Date(a.updated_at)).map(d=>`<button class="record-row" data-document="${d.id}"><span class="record-icon">▤</span><span class="record-main"><b>${esc(d.title)}</b><small>${esc(caseById(d.case_id)?.title||"Document du bureau")} · ${d.signed_at?`Signé par ${esc(d.signer)}`:"Brouillon"}</small></span><span class="status ${d.status==="signed"?"closed":""}">${d.status==="signed"?"Signé":"Brouillon"}</span><span class="chevron">›</span></button>`).join("")}</div>`:`<div class="empty-card"><div class="empty-icon">▤</div><h2>Prépare les documents du bureau</h2><p>Rédige un compte rendu, une autorisation ou une note. Tu pourras ensuite apposer la signature de jeu de Camille Lou.</p><button class="primary" id="new-document-empty">Créer un document</button></div>`}<p class="sim-note">Les signatures enregistrées ici sont des signatures de jeu dans le P.D.E.</p>`;}
function intercomPage(){return `<p class="eyebrow">ACCUEIL DU PALAIS</p><h1>Interphone</h1><p class="muted intro">Une scène de jeu pour accueillir les visiteurs du bâtiment.</p><div class="intercom-card"><div class="camera-scene"><span class="camera-label">ENTRÉE PRINCIPALE · SIMULATION</span>${personSvg(visitor?visitor.name:null)}<div class="door"><div class="door-knob"></div></div><span class="door-state ${visitor?"ringing":""}">${visitor?"APPEL EN COURS":"PORTE FERMÉE"}</span></div><div class="visitor"><span class="visitor-icon">⌁</span><p class="eyebrow">${visitor?"VISITEUR À L’ENTRÉE":"INTERPHONE EN ATTENTE"}</p><h2>${visitor?esc(visitor.name):"Le hall est calme."}</h2><p>${visitor?esc(visitor.reason):"Quand un visiteur sonne, la fiche de l’interphone et la caméra du portail affichent sa présence."}</p>${visitor?`<div class="door-actions"><button class="primary" data-door="open">Ouvrir la porte</button><button class="secondary" data-door="decline">Refuser l’accès</button></div>`:`<button class="primary" id="demo-ring">Simuler une sonnerie</button>`}</div></div><div class="sim-note">La scène n’est pas reliée à une vraie porte ni à un vrai interphone.</div>`;}
function camerasPage(){const views=[{name:"Portail",className:"gate",desc:"Entrée extérieure du Palais",empty:"./assets/cameras/portail-vide.jpg",person:"./assets/cameras/portail-personne.jpg"},{name:"Hall",className:"lobby",desc:"Accueil et grand hall",empty:"./assets/cameras/hall-vide.jpg",person:"./assets/cameras/hall-personne.jpg"},{name:"Couloir nord",className:"corridor",desc:"Couloir des bureaux",empty:"./assets/cameras/couloir-vide.jpg",person:"./assets/cameras/couloir-personne.jpg"},{name:"Archives",className:"archive",desc:"Salle des archives",empty:"./assets/cameras/archives-vide.jpg",person:"./assets/cameras/archives-personne.jpg"}];const seen=cameraPerson||visitor&&{name:visitor.name,camera:"Portail",at:new Date().toISOString()};return `<div class="page-title-row"><div><p class="eyebrow">SÉCURITÉ DU PALAIS</p><h1>Caméras</h1><p class="muted">Images de jeu du Palais · détection simulée de présence.</p></div><button class="secondary" id="camera-refresh">↻ Simuler une détection</button></div><div class="camera-disclaimer">Les images sont des scènes de jeu, pas un flux vidéo réel. Une détection simulée affiche la vue correspondante avec ou sans présence.</div><div class="camera-grid">${views.map((v,i)=>{const person=seen?.camera===v.name;return `<article class="camera-card"><div class="feed ${v.className} ${cameraState[v.name]?"":"feed-off"}"><img class="camera-image" src="${person?v.person:v.empty}" alt="${esc(v.name)} — ${person?"présence détectée":"vue sans personne"}"><span class="camera-label">CAM 0${i+1} · ${esc(v.name.toUpperCase())}</span><span class="rec-dot">${cameraState[v.name]?"● EN DIRECT · SCÈNE DE JEU":"ARRÊT"}</span>${person?`<span class="presence-tag">Présence détectée · ${esc(seen.name)}</span>`:""}</div><div class="camera-meta"><div><b>${esc(v.name)}</b><small>${person?`Présence repérée : ${esc(seen.name)}`:esc(v.desc)}</small></div><button class="secondary small" data-camera-toggle="${esc(v.name)}">${cameraState[v.name]?"Désactiver":"Activer"}</button></div></article>`}).join("")}</div>`;}
function personSvg(name){return `<div class="camera-person" aria-label="Personne visible dans la scène"><svg viewBox="0 0 70 150" aria-hidden="true"><ellipse cx="35" cy="143" rx="21" ry="4" fill="#111" opacity=".45"/><circle cx="35" cy="22" r="13" fill="#192427"/><path d="M22 39Q35 31 48 39L56 91H14Z" fill="#192427"/><path d="M20 90h18v47H24zM35 90h18l-4 47H35z" fill="#10191b"/><path d="M22 45 9 91M48 45 62 86" stroke="#182427" stroke-width="9" stroke-linecap="round"/></svg><b>${esc(name||"Visiteur")}</b></div>`;}
function bind(){
 document.querySelectorAll("[data-page]").forEach(b=>b.addEventListener("click",()=>{page=b.dataset.page;notice="";render();}));
 document.querySelector("#signout")?.addEventListener("click",async()=>{await supabase.auth.signOut();session=null;render();});
 document.querySelectorAll("#new-case,#new-case-empty,#new-case-top").forEach(b=>b.addEventListener("click",openNewCase));
 document.querySelector("#new-appointment")?.addEventListener("click",()=>openAppointment());document.querySelector("#new-appointment-empty")?.addEventListener("click",()=>openAppointment());document.querySelector("#new-appointment-home")?.addEventListener("click",()=>openAppointment());
 document.querySelector("#new-call")?.addEventListener("click",()=>openCall());document.querySelector("#simulate-incoming")?.addEventListener("click",simulateIncoming);
 document.querySelector("#compose-mail,#compose-mail-empty")?.addEventListener("click",()=>openMailComposer());document.querySelectorAll("[data-mail-view]").forEach(b=>b.addEventListener("click",()=>{mailboxView=b.dataset.mailView;render();}));document.querySelectorAll("[data-mail]").forEach(b=>b.addEventListener("click",()=>openMailDetail(mailbox.find(m=>m.id===b.dataset.mail))));
 document.querySelector("#new-analysis")?.addEventListener("click",()=>openAnalysis());document.querySelector("#new-analysis-empty")?.addEventListener("click",()=>openAnalysis());
 document.querySelector("#new-document")?.addEventListener("click",()=>openDocument());document.querySelector("#new-document-empty")?.addEventListener("click",()=>openDocument());
 document.querySelector("#close-notice")?.addEventListener("click",()=>{notice="";render();});
 document.querySelector("#demo-ring")?.addEventListener("click",ringIntercom);document.querySelectorAll("[data-door]").forEach(b=>b.addEventListener("click",()=>answerIntercom(b.dataset.door)));
 document.querySelectorAll("[data-camera-toggle]").forEach(b=>b.addEventListener("click",()=>toggleCamera(b.dataset.cameraToggle)));document.querySelector("#camera-refresh")?.addEventListener("click",simulateCameraDetection);
 document.querySelectorAll("[data-open]").forEach(b=>b.addEventListener("click",()=>openCase(b.dataset.open)));
 document.querySelectorAll("[data-appointment]").forEach(b=>b.addEventListener("click",()=>openAppointment(appointments.find(a=>a.id===b.dataset.appointment))));
 document.querySelectorAll("[data-call]").forEach(b=>b.addEventListener("click",()=>openCallDetail(calls.find(a=>a.id===b.dataset.call))));
 document.querySelectorAll("[data-analysis]").forEach(b=>b.addEventListener("click",()=>openAnalysis(analyses.find(a=>a.id===b.dataset.analysis))));
 document.querySelectorAll("[data-document]").forEach(b=>b.addEventListener("click",()=>openDocumentDetail(documents.find(a=>a.id===b.dataset.document))));
}
async function login(e){e.preventDefault();const f=new FormData(e.currentTarget);const{error}=await supabase.auth.signInWithPassword({email:f.get("email"),password:f.get("password")});if(error){notice="Connexion impossible. Vérifie ton adresse et ton mot de passe.";renderLogin();}}
function caseById(id){return cases.find(c=>c.id===id);}
function modalShell(html,className="modal"){const d=document.createElement("dialog");d.className=className;d.innerHTML=html;d.addEventListener("close",()=>d.remove(),{once:true});document.body.append(d);d.showModal();d.querySelector("input,textarea,select")?.focus();return d;}
function closeModal(d){if(d?.open)d.close();else d?.remove();}
async function saveCaseRow(row,id){const q=id?supabase.from("cases").update({...row,updated_at:new Date().toISOString()}).eq("id",id):supabase.from("cases").insert({...row,created_by:session.user.id,updated_at:new Date().toISOString()});const{error}=await q;if(error)throw error;}
function openNewCase(){const d=modalShell(`<form id="case-form"><button class="modal-close" type="button" data-close>×</button><p class="eyebrow">NOUVELLE ENQUÊTE</p><h2>Ouvrir un dossier</h2><label>Nom du dossier<input name="title" required maxlength="100" placeholder="Ex. Affaire Tomaso"></label><label>Personnes concernées<input name="people" maxlength="240"></label><label>Première note<textarea name="note" rows="4" placeholder="Contexte ou motif de l’enquête"></textarea></label><button class="primary full">Enregistrer dans le cloud</button></form>`);d.querySelector("[data-close]").onclick=()=>closeModal(d);d.querySelector("form").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await saveCaseRow({title:String(f.get("title")).trim(),people:String(f.get("people")||"").trim(),note:String(f.get("note")||"").trim(),status:"open",case_number:`PDE-${String(cases.length+1).padStart(3,"0")}`});notice="Dossier enregistré et synchronisé.";await loadWorkspace();}catch{notice="Le dossier n’a pas pu être enregistré.";}closeModal(d);render();};}
async function openCase(id){const c=caseById(id);if(!c)return;const [upRes,apRes,callRes,analysisRes,docRes,mailRes]=await Promise.all([supabase.from("case_updates").select("*").eq("case_id",c.id).order("sort_order",{ascending:true}).order("created_at",{ascending:true}),supabase.from("appointments").select("*").eq("case_id",c.id).order("starts_at",{ascending:false}),supabase.from("call_logs").select("*").eq("case_id",c.id).order("occurred_at",{ascending:false}),supabase.from("lab_analyses").select("*").eq("case_id",c.id).order("created_at",{ascending:false}),supabase.from("documents").select("*").eq("case_id",c.id).order("updated_at",{ascending:false}),supabase.from("mailbox_messages").select("*").eq("case_id",c.id).order("created_at",{ascending:false})]);const updates=upRes.data||[],relatedAppointments=apRes.data||[],relatedCalls=callRes.data||[],relatedAnalyses=analysisRes.data||[],relatedDocs=docRes.data||[],relatedMail=mailRes.data||[];if(upRes.error)notice="Impossible de récupérer l’historique de ce dossier.";const d=modalShell(`<form id="case-update-form"><button class="modal-close" type="button" data-close>×</button><p class="eyebrow">${esc(c.case_number)} · ${statusLabel(c.status).toUpperCase()}</p><h2>${esc(c.title)}</h2><p class="muted">${esc(c.people||"Personnes à préciser")}</p><div class="case-summary-row"><div class="note-box"><b>Résumé du dossier</b><br>${esc(c.note||"Aucun résumé ajouté.")}</div><button class="secondary small" type="button" id="edit-case-summary">Modifier le résumé</button></div><h3 class="subheading">Historique et notes</h3>${updates.length?`<div class="timeline">${updates.map(u=>`<article><time>${u.occurred_at?dateTimeLabel(u.occurred_at):"Date originale non indiquée · texte retranscrit"}</time><p>${esc(u.body)}</p><button class="text-button note-edit" type="button" data-edit-update="${u.id}">Modifier cette note</button></article>`).join("")}</div>`:`<div class="empty-history">Aucune note enregistrée pour le moment.</div>`}<label>Ajouter une nouvelle avancée<textarea name="update" rows="4" placeholder="Écris ce qui s’est passé…"></textarea></label><label>Statut du dossier<select name="status"><option value="open" ${c.status==="open"?"selected":""}>En cours</option><option value="review" ${c.status==="review"?"selected":""}>À analyser</option><option value="closed" ${c.status==="closed"?"selected":""}>Terminé</option></select></label><button class="primary full">Enregistrer l’avancée et le statut</button><section class="case-linked"><h3 class="subheading">Activité synchronisée</h3>${relatedMail.length?`<h4>Messagerie · ${relatedMail.length}</h4>${relatedMail.map(m=>`<button class="linked-row" type="button" data-linked-mail="${m.id}"><b>${m.direction==="inbound"?esc(m.sender_name):`À : ${esc(m.recipient)}`} · ${esc(m.subject)}</b><small>${dateTimeLabel(m.created_at)} · ${esc((m.body||"").replace(/\s+/g," ").slice(0,110))}</small></button>`).join("")}`:`<p class="linked-empty">Aucun courriel lié.</p>`}${relatedAnalyses.length?`<h4>Laboratoire · ${relatedAnalyses.length}</h4>${relatedAnalyses.map(a=>`<div class="linked-card"><b>${esc(a.evidence)} · ${analysisStatus(a.status)}</b>${a.reference?`<small>Réf. ${esc(a.reference)}</small>`:""}${a.findings?`<p>${esc(a.findings)}</p>`:"<small>Résultat en attente.</small>"}</div>`).join("")}`:`<p class="linked-empty">Aucune analyse liée.</p>`}${relatedAppointments.length?`<h4>Rendez-vous et comptes rendus · ${relatedAppointments.length}</h4>${relatedAppointments.map(a=>`<div class="linked-card"><b>${esc(a.title)} · ${dateTimeLabel(a.starts_at)}</b><small>${esc(a.contact||"")} · ${esc(a.status==="completed"?"Terminé":"Prévu")}</small>${a.notes?`<p>${esc(a.notes)}</p>`:"<small>Compte rendu à compléter.</small>"}</div>`).join("")}`:""}${relatedCalls.length?`<h4>Appels · ${relatedCalls.length}</h4>${relatedCalls.map(a=>`<div class="linked-card"><b>${esc(a.contact)} · ${dateTimeLabel(a.occurred_at)}</b><p>${esc(a.summary)}</p>${a.follow_up?`<small>Suite : ${esc(a.follow_up)}</small>`:""}</div>`).join("")}`:""}${relatedDocs.length?`<h4>Documents · ${relatedDocs.length}</h4>${relatedDocs.map(a=>`<div class="linked-card"><b>${esc(a.title)}</b><small>${a.status==="signed"?`Signé par ${esc(a.signer)}`:"Brouillon"}</small></div>`).join("")}`:""}</section><button class="danger full" type="button" id="delete-case">Supprimer ce dossier</button></form>` ,"modal case-detail-modal");d.querySelector("[data-close]").onclick=()=>closeModal(d);d.querySelectorAll("[data-edit-update]").forEach(b=>b.onclick=()=>{const u=updates.find(x=>x.id===b.dataset.editUpdate);if(u)editCaseUpdate(c,u,d);});d.querySelector("#edit-case-summary").onclick=()=>editCaseSummary(c,d);d.querySelectorAll("[data-linked-mail]").forEach(b=>b.onclick=()=>openMailDetail(mailbox.find(m=>m.id===b.dataset.linkedMail)));d.querySelector("form").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const body=String(f.get("update")||"").trim(),status=String(f.get("status"));try{if(body){const order=Math.max(0,...updates.map(u=>u.sort_order||0))+1;const{error}=await supabase.from("case_updates").insert({case_id:c.id,created_by:session.user.id,body,occurred_at:new Date().toISOString(),sort_order:order});if(error)throw error;}const{error}=await supabase.from("cases").update({status,updated_at:new Date().toISOString()}).eq("id",c.id);if(error)throw error;notice=body?"Avancée ajoutée au dossier et synchronisée.":"Statut du dossier mis à jour.";await loadWorkspace();}catch{notice="La modification du dossier n’a pas pu être enregistrée.";}closeModal(d);render();};d.querySelector("#delete-case").onclick=()=>confirmDelete(c,d);}
function editCaseUpdate(c,u,parent){const d=modalShell(`<form><button class="modal-close" type="button" data-close>×</button><p class="eyebrow">${esc(c.case_number)} · NOTE D’ENQUÊTE</p><h2>Modifier cette note</h2><label>Contenu<textarea name="body" rows="8" required>${esc(u.body)}</textarea></label><button class="primary full">Enregistrer la note</button></form>`);d.querySelector("[data-close]").onclick=()=>closeModal(d);d.querySelector("form").onsubmit=async e=>{e.preventDefault();const body=String(new FormData(e.currentTarget).get("body")).trim();const{error}=await supabase.from("case_updates").update({body}).eq("id",u.id);if(error){notice="La note n’a pas pu être modifiée. Recharge le dossier et réessaie.";closeModal(d);render();return;}notice="Note modifiée et synchronisée.";await loadWorkspace();closeModal(d);closeModal(parent);render();openCase(c.id);};}
function editCaseSummary(c,parent){const d=modalShell(`<form><button class="modal-close" type="button" data-close>×</button><p class="eyebrow">${esc(c.case_number)} · DOSSIER</p><h2>Modifier le résumé</h2><label>Résumé<textarea name="note" rows="8">${esc(c.note||"")}</textarea></label><button class="primary full">Enregistrer le résumé</button></form>`);d.querySelector("[data-close]").onclick=()=>closeModal(d);d.querySelector("form").onsubmit=async e=>{e.preventDefault();const note=String(new FormData(e.currentTarget).get("note")||"").trim();const{error}=await supabase.from("cases").update({note,updated_at:new Date().toISOString()}).eq("id",c.id);if(error){notice="Le résumé n’a pas pu être enregistré.";closeModal(d);render();return;}await loadWorkspace();notice="Résumé mis à jour et synchronisé.";closeModal(d);closeModal(parent);render();openCase(c.id);}}
function confirmDelete(c,parent){const d=modalShell(`<div><p class="eyebrow">CONFIRMATION POUR CE DOSSIER</p><h2>Supprimer ${esc(c.case_number)} · ${esc(c.title)} ?</h2><p class="delete-summary">Cette action supprimera définitivement ce dossier et ses notes d’enquête. Les rendez-vous, appels, analyses et documents associés seront conservés dans leurs espaces, mais ne seront plus rattachés au dossier.</p><div class="delete-detail"><b>Dossier concerné</b><span>${esc(c.title)}</span><small>${esc(c.case_number)} · ${statusLabel(c.status)}</small></div><p class="delete-instruction">Choisis <b>« Oui, supprimer ce dossier »</b> pour confirmer. Sinon, appuie sur « Annuler ».</p><div class="delete-actions"><button class="secondary" id="cancel-delete">Annuler</button><button class="danger" id="confirm-delete">Oui, supprimer ce dossier</button></div></div>`,"modal delete-confirm");d.querySelector("#cancel-delete").onclick=()=>closeModal(d);d.querySelector("#confirm-delete").onclick=async()=>{const b=d.querySelector("#confirm-delete");b.disabled=true;b.textContent="Suppression…";const{error}=await supabase.from("cases").delete().eq("id",c.id);if(error){notice="La suppression a échoué. Vérifie les règles Supabase.";b.disabled=false;b.textContent="Oui, supprimer ce dossier";return;}closeModal(d);closeModal(parent);notice=`${c.case_number} · ${c.title} a été supprimé avec ses notes d’enquête.`;await loadWorkspace();render();};}
function openAppointment(record=null){const a=record||{};const d=modalShell(`<form id="appointment-form"><button class="modal-close" type="button" data-close>×</button><p class="eyebrow">AGENDA DU PALAIS</p><h2>${a.id?"Modifier le rendez-vous":"Ajouter un rendez-vous"}</h2><label>Objet<input name="title" required maxlength="120" value="${esc(a.title)}" placeholder="Ex. Entretien avec la famille Dajo"></label><div class="form-grid"><label>Personne reçue<input name="contact" value="${esc(a.contact)}"></label><label>Type<select name="kind">${["Entretien","Visite","Réunion","Rappel","Autre"].map(x=>`<option ${a.kind===x?"selected":""}>${x}</option>`).join("")}</select></label></div><label>Date et heure<input type="datetime-local" name="starts_at" required value="${localDateTime(a.starts_at)}"></label><label>Salle ou lieu<input name="location" value="${esc(a.location)}" placeholder="Ex. Salle Saphir"></label><label>Dossier lié<select name="case_id">${caseOptions(a.case_id)}</select></label><label>Compte rendu / notes<textarea name="notes" rows="5" placeholder="Ajoute ici ce qui s’est dit pendant le rendez-vous…">${esc(a.notes)}</textarea></label><label>État<select name="status"><option value="planned" ${a.status!=="completed"&&a.status!=="cancelled"?"selected":""}>Prévu</option><option value="completed" ${a.status==="completed"?"selected":""}>Terminé</option><option value="cancelled" ${a.status==="cancelled"?"selected":""}>Annulé</option></select></label><button class="primary full">${a.id?"Enregistrer les changements":"Enregistrer le rendez-vous"}</button></form>`);d.querySelector("[data-close]").onclick=()=>closeModal(d);d.querySelector("form").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const row={title:String(f.get("title")).trim(),contact:String(f.get("contact")||"").trim(),kind:String(f.get("kind")),starts_at:new Date(f.get("starts_at")).toISOString(),location:String(f.get("location")||"").trim(),case_id:f.get("case_id")||null,notes:String(f.get("notes")||"").trim(),status:String(f.get("status")),updated_at:new Date().toISOString()};try{const q=a.id?supabase.from("appointments").update(row).eq("id",a.id):supabase.from("appointments").insert({...row,created_by:session.user.id});const{error}=await q;if(error)throw error;notice="Rendez-vous et notes enregistrés.";await loadWorkspace();}catch{notice="Le rendez-vous n’a pas pu être enregistré.";}closeModal(d);render();};}
function openCall(prefill={}){const c=prefill;const d=modalShell(`<form id="call-form"><button class="modal-close" type="button" data-close>×</button><p class="eyebrow">JOURNAL DU BUREAU</p><h2>${c.simulated?"Appel entrant simulé":"Consigner un appel"}</h2>${c.simulated?`<div class="incoming-banner">☎ ${esc(c.contact)} appelle le bureau</div>`:""}<div class="form-grid"><label>Personne<input name="contact" required value="${esc(c.contact)}" placeholder="Nom du correspondant"></label><label>Sens de l’appel<select name="direction"><option value="inbound" ${c.direction==="inbound"?"selected":""}>Entrant</option><option value="outbound" ${c.direction==="outbound"?"selected":""}>Sortant</option></select></label></div><label>Numéro (facultatif)<input name="phone" value="${esc(c.phone)}"></label><label>Dossier lié<select name="case_id">${caseOptions(c.case_id)}</select></label><label>Ce qui s’est passé<textarea name="summary" rows="4" required placeholder="Résumé de l’appel et informations communiquées…">${esc(c.summary)}</textarea></label><label>Suite à donner<textarea name="follow_up" rows="3" placeholder="Rappel, document à préparer, personne à prévenir…">${esc(c.follow_up)}</textarea></label><div class="delete-actions"><button class="secondary" type="button" data-close>Annuler</button>${c.simulated?`<button class="secondary" type="button" id="miss-call">Ne pas répondre</button>`:""}<button class="primary">Enregistrer l’appel</button></div></form>`);d.querySelectorAll("[data-close]").forEach(b=>b.onclick=()=>closeModal(d));d.querySelector("#miss-call")?.addEventListener("click",async()=>{const{error}=await supabase.from("call_logs").insert({created_by:session.user.id,contact:c.contact,direction:"inbound",summary:"Appel entrant simulé — aucune réponse.",follow_up:""});if(!error){notice=`Appel manqué de ${c.contact} consigné.`;await loadWorkspace();}closeModal(d);render();});d.querySelector("form").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const{error}=await supabase.from("call_logs").insert({created_by:session.user.id,contact:String(f.get("contact")).trim(),direction:String(f.get("direction")),phone:String(f.get("phone")||"").trim(),case_id:f.get("case_id")||null,summary:String(f.get("summary")).trim(),follow_up:String(f.get("follow_up")||"").trim(),occurred_at:new Date().toISOString()});if(error)throw error;notice="Appel consigné dans le journal.";await loadWorkspace();}catch{notice="L’appel n’a pas pu être enregistré.";}closeModal(d);render();};}
function simulateIncoming(){const names=["Élise Martin","Madame Dajo","Un coursier","M. Coureur"];const contact=names[Math.floor(Math.random()*names.length)];openCall({simulated:true,contact,direction:"inbound",summary:"Appel entrant simulé. ",follow_up:""});}
function openCallDetail(c){if(!c)return;modalShell(`<button class="modal-close" type="button" data-close>×</button><p class="eyebrow">${c.direction==="inbound"?"APPEL ENTRANT":"APPEL SORTANT"} · ${dateTimeLabel(c.occurred_at)}</p><h2>${esc(c.contact)}</h2>${c.phone?`<p>${esc(c.phone)}</p>`:""}<div class="note-box">${esc(c.summary)}</div>${c.follow_up?`<h3>Suite à donner</h3><p>${esc(c.follow_up)}</p>`:""}${c.case_id?`<p class="muted">Dossier : ${esc(caseById(c.case_id)?.title||"")}</p>`:""}`).querySelector("[data-close]").onclick=e=>closeModal(e.target.closest("dialog"));}
function openAnalysis(record=null){const a=record||{};const d=modalShell(`<form id="analysis-form"><button class="modal-close" type="button" data-close>×</button><p class="eyebrow">LABORATOIRE DU PALAIS</p><h2>${a.id?"Suivi de l’analyse":"Nouvelle demande d’analyse"}</h2><label>Élément à analyser<input name="evidence" required value="${esc(a.evidence)}" placeholder="Ex. Bijoux, foulard, ADN"></label><label>Référence / numéro de scellé<input name="reference" value="${esc(a.reference)}" placeholder="À renseigner"></label><label>Dossier lié<select name="case_id">${caseOptions(a.case_id)}</select></label><label>Autorisation / personnes ayant donné leur accord<input name="requested_by" value="${esc(a.requested_by)}"></label><label>Précision sur l’autorisation<textarea name="authorization_note" rows="2">${esc(a.authorization_note)}</textarea></label><label>État de l’analyse<select name="status"><option value="requested" ${a.status==="requested"?"selected":""}>Demandée</option><option value="in_progress" ${a.status==="in_progress"?"selected":""}>En cours d’analyse</option><option value="complete" ${a.status==="complete"?"selected":""}>Résultat reçu</option></select></label><label>Résultat / observations<textarea name="findings" rows="4" placeholder="Saisis le résultat communiqué par le laboratoire…">${esc(a.findings)}</textarea></label><button class="primary full">${a.id?"Enregistrer le suivi":"Enregistrer la demande"}</button></form>`);d.querySelector("[data-close]").onclick=()=>closeModal(d);d.querySelector("form").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const row={evidence:String(f.get("evidence")).trim(),reference:String(f.get("reference")||"").trim(),case_id:f.get("case_id")||null,requested_by:String(f.get("requested_by")||"").trim(),authorization_note:String(f.get("authorization_note")||"").trim(),status:String(f.get("status")),findings:String(f.get("findings")||"").trim(),updated_at:new Date().toISOString()};try{const q=a.id?supabase.from("lab_analyses").update(row).eq("id",a.id):supabase.from("lab_analyses").insert({...row,created_by:session.user.id});const{error}=await q;if(error)throw error;if(row.status==="complete"&&row.findings&&a.status!=="complete"){const summary=`Résultat du laboratoire · ${row.evidence}${row.reference?` (réf. ${row.reference})`:""} : ${row.findings}`;if(row.case_id){await supabase.from("case_updates").insert({case_id:row.case_id,created_by:session.user.id,body:summary,occurred_at:new Date().toISOString(),sort_order:Date.now()});}await supabase.from("mailbox_messages").insert({created_by:session.user.id,direction:"inbound",sender_name:"Laboratoire du Palais",sender_email:"laboratoire@exemple.pde",recipient:"Camille Lou",case_id:row.case_id||null,subject:`Résultats d’analyse · ${row.evidence}`,body:`Madame la Directrice,\n\nLe laboratoire a terminé l’analyse de ${row.evidence}${row.reference?` (référence ${row.reference})`:""}.\n\nRésultat : ${row.findings}\n\nLe résultat complet est conservé dans le dossier associé.\n\nLaboratoire du Palais`});}notice="Analyse enregistrée dans le laboratoire et synchronisée avec le dossier.";await loadWorkspace();}catch{notice="L’analyse n’a pas pu être enregistrée.";}closeModal(d);render();};}
function openDocument(record=null){const d0=record||{};const d=modalShell(`<form id="document-form"><button class="modal-close" type="button" data-close>×</button><p class="eyebrow">SECRÉTARIAT DU PALAIS</p><h2>${d0.id?"Modifier le brouillon":"Rédiger un document"}</h2><label>Titre<input name="title" required maxlength="140" value="${esc(d0.title)}" placeholder="Ex. Compte rendu d’entretien"></label><label>Dossier lié<select name="case_id">${caseOptions(d0.case_id)}</select></label><label>Texte du document<textarea name="content" rows="12" required placeholder="Rédige ton compte rendu ou ton document ici…">${esc(d0.content)}</textarea></label><button class="primary full">Enregistrer le brouillon</button></form>`);d.querySelector("[data-close]").onclick=()=>closeModal(d);d.querySelector("form").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const row={title:String(f.get("title")).trim(),case_id:f.get("case_id")||null,content:String(f.get("content")).trim(),status:"draft",updated_at:new Date().toISOString()};try{const q=d0.id?supabase.from("documents").update(row).eq("id",d0.id):supabase.from("documents").insert({...row,created_by:session.user.id});const{error}=await q;if(error)throw error;notice="Document enregistré. Tu peux le rouvrir pour le signer.";await loadWorkspace();}catch{notice="Le document n’a pas pu être enregistré.";}closeModal(d);render();};}
function openDocumentDetail(d0){if(!d0)return;const d=modalShell(`<button class="modal-close" type="button" data-close>×</button><p class="eyebrow">${d0.status==="signed"?"DOCUMENT SIGNÉ":"BROUILLON"}</p><h2>${esc(d0.title)}</h2>${d0.case_id?`<p class="muted">Dossier : ${esc(caseById(d0.case_id)?.title||"")}</p>`:""}<article class="document-paper">${esc(d0.content).replace(/\n/g,"<br>")}</article>${d0.status==="signed"?`<div class="signature-record"><p>Signé par <b>${esc(d0.signer)}</b></p>${d0.signature_data?`<img src="${esc(d0.signature_data)}" alt="Signature manuscrite de ${esc(d0.signer)}">`:""}<small>${dateTimeLabel(d0.signed_at)}</small></div>`:`<div class="delete-actions"><button class="secondary" id="edit-document">Modifier le brouillon</button><button class="primary" id="sign-document">Signer ce document</button></div>`}`);d.querySelector("[data-close]").onclick=()=>closeModal(d);d.querySelector("#edit-document")?.addEventListener("click",()=>{closeModal(d);openDocument(d0);});d.querySelector("#sign-document")?.addEventListener("click",()=>{closeModal(d);signDocument(d0);});}
function signDocument(doc){const d=modalShell(`<form id="sign-form"><button class="modal-close" type="button" data-close>×</button><p class="eyebrow">SIGNATURE DU P.D.E.</p><h2>${esc(doc.title)}</h2><p class="muted">Relis le document puis signe-le au nom de la direction. Cette signature est enregistrée dans l’espace de jeu.</p><label>Nom du signataire<input name="signer" required value="Camille Lou"></label><label>Signature manuscrite<canvas class="signature-pad" width="560" height="155"></canvas></label><button class="secondary small" type="button" id="clear-signature">Effacer le tracé</button><button class="primary full">Confirmer et signer</button></form>`);d.querySelector("[data-close]").onclick=()=>closeModal(d);const canvas=d.querySelector("canvas"),ctx=canvas.getContext("2d");ctx.strokeStyle="#203338";ctx.lineWidth=3;ctx.lineCap="round";let drawing=false;const point=e=>{const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height};};canvas.onpointerdown=e=>{drawing=true;canvas.setPointerCapture(e.pointerId);const p=point(e);ctx.beginPath();ctx.moveTo(p.x,p.y);};canvas.onpointermove=e=>{if(!drawing)return;const p=point(e);ctx.lineTo(p.x,p.y);ctx.stroke();};canvas.onpointerup=()=>drawing=false;canvas.onpointercancel=()=>drawing=false;d.querySelector("#clear-signature").onclick=()=>ctx.clearRect(0,0,canvas.width,canvas.height);d.querySelector("form").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const{error}=await supabase.from("documents").update({status:"signed",signer:String(f.get("signer")).trim(),signature_data:canvas.toDataURL("image/png"),signed_at:new Date().toISOString(),updated_at:new Date().toISOString()}).eq("id",doc.id);if(error)throw error;notice="Document signé et enregistré.";await loadWorkspace();}catch{notice="La signature n’a pas pu être enregistrée.";}closeModal(d);render();};}
function openMailComposer(reply=null,draft=""){const d=modalShell(`<form id="mail-form"><button class="modal-close" type="button" data-close>×</button><p class="eyebrow">MESSAGERIE DU PALAIS · JEU</p><h2>${reply?"Répondre au message":"Nouveau courriel"}</h2><label>Destinataire<input name="recipient" required value="${esc(reply?.sender_email||"")}" placeholder="Nom ou adresse fictive"></label><label>Dossier associé<select name="case_id">${caseOptions(reply?.case_id)}</select></label><label>Objet<input name="subject" required maxlength="180" value="${esc(reply?`Re : ${reply.subject}`:"")}"></label><div class="mail-draft-head"><label for="mail-body">Message</label><button class="secondary small" type="button" id="lili-draft">✦ Lili · proposer un brouillon</button></div><textarea id="mail-body" name="body" rows="9" required placeholder="Rédige ton message…">${esc(draft)}</textarea><p class="sim-note">Lili prépare un texte modifiable à partir du message et du dossier. Relis-le avant l’envoi.</p><fieldset class="reply-settings"><legend>Réponse du correspondant</legend><label class="reply-auto"><input name="auto_reply" type="checkbox" checked><span>Recevoir une réponse automatique de jeu</span></label><label>Après<select name="reply_delay"><option value="5">5 minutes</option><option value="10" selected>10 minutes</option><option value="20">20 minutes</option><option value="60">1 heure</option><option value="120">2 heures</option></select></label></fieldset><button class="primary full">Enregistrer et envoyer dans le jeu</button><p class="sim-note">Les échanges sont fictifs : aucun vrai courriel n’est envoyé.</p></form>`);d.querySelector("[data-close]").onclick=()=>closeModal(d);const form=d.querySelector("form");const delaySelect=form.elements.reply_delay;form.elements.auto_reply.onchange=()=>{delaySelect.disabled=!form.elements.auto_reply.checked;};d.querySelector("#lili-draft").onclick=()=>{const caseId=form.elements.case_id.value;const c=caseById(caseId);form.elements.body.value=makeLiliDraft({reply,caseInfo:c,subject:form.elements.subject.value,recipient:form.elements.recipient.value});};form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form);const auto=Boolean(form.elements.auto_reply.checked);const sent={created_by:session.user.id,direction:"outbound",sender_name:"Camille Lou",sender_email:"camille.pde@proton.me",recipient:String(f.get("recipient")).trim(),case_id:f.get("case_id")||null,subject:String(f.get("subject")).trim(),body:String(f.get("body")).trim(),reply_to:reply?.id||null,reply_delay_minutes:auto?Number(f.get("reply_delay")):null};try{const{error}=await supabase.from("mailbox_messages").insert(sent).select().single();if(error)throw error;notice=auto?`Message envoyé dans le jeu. Une réponse est prévue après ${delayLabel(sent.reply_delay_minutes)}.`:"Message envoyé dans le jeu, sans réponse automatique.";await loadWorkspace();closeModal(d);render();}catch{notice="Le message n’a pas pu être enregistré. Vérifie la connexion de la messagerie au cloud.";closeModal(d);render();}};}
function delayLabel(minutes){return minutes<60?`${minutes} minutes`:minutes===60?"1 heure":"2 heures";}
function makeLiliDraft({reply,caseInfo,subject,recipient}){const name=(recipient||reply?.sender_name||"Madame, Monsieur").split(/[<@]/)[0].replace(/[._-]+/g," ").trim();const title=caseInfo?.title||reply?.subject?.replace(/^re\s*:\s*/i,"")||subject||"votre message";const incoming=reply?.body||"";let purpose="Je vous remercie pour les éléments transmis. Je les prends en compte dans le suivi du dossier et reviendrai vers vous dès que j’aurai des informations confirmées.";if(/rendez|disponib|rencontr|horaire|visite/i.test(`${incoming} ${subject}`))purpose="Je vous remercie pour votre retour. Nous pouvons convenir d’un rendez-vous afin d’échanger sur ces éléments. Merci de me proposer vos disponibilités.";else if(/résultat|analyse|laboratoire|preuve|élément/i.test(`${incoming} ${subject}`))purpose="J’ai bien pris connaissance de votre message. Je fais le point avec le laboratoire et vous transmettrai les conclusions dès qu’elles seront disponibles.";else if(/urgent|immédiat|aujourd’hui/i.test(`${incoming} ${subject}`))purpose="J’ai bien reçu votre message et prends note du caractère urgent de la situation. Je reviens vers vous dès que possible après vérification des éléments.";return `Bonjour ${name||"Madame, Monsieur"},\n\nJe reviens vers vous au sujet de ${title}. ${purpose}\n\nBien cordialement,\nCamille Lou\nDirectrice · Palais des Enquêtes`;}
function makeContextualReply(m,senderName){const c=caseById(m.case_id);const text=`${m.subject} ${m.body}`.toLowerCase();const subject=m.subject||"votre message";const who=senderName||"Votre correspondant";let body;if(/rendez|disponib|rencontr|horaire|visite/.test(text))body=`Bonjour,\n\nMerci pour votre retour au sujet de ${c?.title||subject}. Je vous confirme que je suis disponible pour en discuter. Je vous envoie les détails du rendez-vous dès que l’horaire est fixé.\n\nBien cordialement,\n${who}`;else if(/résultat|analyse|laboratoire|preuve|élément/.test(text))body=`Bonjour,\n\nJ’ai bien reçu votre demande concernant ${c?.title||subject}. L’analyse suit son cours. Je vous transmettrai les constatations dès que le rapport aura été validé par le laboratoire.\n\nCordialement,\n${who}`;else body=`Bonjour,\n\nMerci pour votre message concernant ${c?.title||subject}. J’ai bien pris note des éléments transmis et je les ajoute au suivi. Je vous recontacte dès que j’ai une information confirmée.\n\nBien cordialement,\n${who}`;return body;}
async function autoReplyTo(m){if(!session||!m||mailbox.some(x=>x.direction==="inbound"&&x.reply_to===m.id))return;const c=caseById(m.case_id);const correspondent=(m.recipient||"").split(/[<@]/)[0].replace(/[._-]+/g," ").trim()||"Le correspondant";try{const{error}=await supabase.from("mailbox_messages").insert({created_by:session.user.id,direction:"inbound",sender_name:correspondent,sender_email:m.recipient||"correspondant@exemple.pde",recipient:"Camille Lou",case_id:m.case_id||null,subject:`Re : ${m.subject}`,body:makeContextualReply(m,correspondent),reply_to:m.id});if(error)throw error;notice=`Réponse reçue de ${correspondent}${c?` · ${c.case_number}`:""}.`;await loadWorkspace();if(page==="mailbox")mailboxView="inbox";render();}catch{notice="La réponse automatique de jeu n’a pas pu être reçue.";render();}}
async function checkScheduledReplies(){if(!session||autoReplyBusy)return;autoReplyBusy=true;try{const due=mailbox.filter(m=>m.direction==="outbound"&&m.reply_delay_minutes&&Date.now()>=new Date(m.created_at).getTime()+Number(m.reply_delay_minutes)*60000&&!mailbox.some(x=>x.direction==="inbound"&&x.reply_to===m.id));for(const m of due)await autoReplyTo(m);}finally{autoReplyBusy=false;}}
function openMailDetail(m){if(!m)return;const thread=[...mailbox].filter(x=>x.id===m.id||x.reply_to===m.id||x.id===m.reply_to).sort((a,b)=>new Date(a.created_at)-new Date(b.created_at));const d=modalShell(`<button class="modal-close" type="button" data-close>×</button><p class="eyebrow">${m.direction==="inbound"?"MESSAGE REÇU":"MESSAGE ENVOYÉ"} · ${dateTimeLabel(m.created_at)}</p><h2>${esc(m.subject||"(sans objet)")}</h2><p class="muted">${m.direction==="inbound"?`De : ${esc(m.sender_name)}${m.sender_email?` · ${esc(m.sender_email)}`:""}`:`À : ${esc(m.recipient)}`}</p>${m.case_id?`<p class="muted">Dossier : ${esc(caseById(m.case_id)?.case_number||"")} · ${esc(caseById(m.case_id)?.title||"")}</p>`:""}${thread.map(x=>`<article class="mail-thread"><b>${x.direction==="inbound"?esc(x.sender_name):"Camille Lou"}</b><small>${dateTimeLabel(x.created_at)}</small><p>${esc(x.body).replace(/\n/g,"<br>")}</p></article>`).join("")}${m.direction==="inbound"?`<button class="primary full" id="reply-mail">Répondre</button>`:""}<p class="sim-note">Correspondance fictive synchronisée avec le dossier associé.</p>`);d.querySelector("[data-close]").onclick=()=>closeModal(d);d.querySelector("#reply-mail")?.addEventListener("click",()=>{closeModal(d);openMailComposer(m);});}
const autoMailTemplates=[{from:"Un correspondant",email:"correspondant@exemple.pde",subject:"Une précision pour le dossier",body:(c,n)=>`Bonjour Camille,\n\nJe repensais au dossier ${c.title}. Je viens de retrouver une précision qui pourrait vous aider : ${n}. Pouvez-vous me dire si vous souhaitez que je passe au Palais ?\n\nÉlise Martin`,note:"un détail de l’entretien qui m’avait échappé"},{from:"Secrétariat du Palais",email:"secretariat@exemple.pde",subject:"Point de suivi",body:(c,n)=>`Camille,\n\nPetit point sur ${c.case_number} · ${c.title} : ${n}. J’ai classé le document dans le dossier et reste disponible si tu veux que je prépare la suite.\n\nLe secrétariat`,note:"les pièces ont été rapprochées du compte rendu précédent"},{from:"Laboratoire du Palais",email:"laboratoire@exemple.pde",subject:"Suivi de l’analyse",body:(c,n)=>`Madame la Directrice,\n\nConcernant ${c.case_number} · ${c.title}, le laboratoire vous informe que ${n}. Le rapport détaillé sera joint au dossier dès sa validation.\n\nLaboratoire du Palais`,note:"les vérifications complémentaires se poursuivent"},{from:"Un correspondant",email:"correspondant@exemple.pde",subject:"Suite à notre échange",body:(c,n)=>`Bonjour,\n\nJe reviens vers vous au sujet de ${c.title}. ${n}. Je reste joignable pour en reparler.\n\nBien à vous`,note:"je peux confirmer le créneau que nous avions évoqué"}];
async function automaticMailArrival(){if(!session)return;try{const last=mailbox.find(m=>m.direction==="inbound");if(last&&Date.now()-new Date(last.created_at).getTime()<180000)return;const active=cases.filter(c=>c.status!=="closed");if(!active.length)return;const c=active[Math.floor(Math.random()*active.length)];const template=autoMailTemplates[Math.floor(Math.random()*autoMailTemplates.length)];const contact=(c.people||"").split(/[,/;]/)[0].trim();const sender=template.from==="Un correspondant"?(contact||template.from):template.from;const{error}=await supabase.from("mailbox_messages").insert({created_by:session.user.id,direction:"inbound",sender_name:sender,sender_email:contact?`${contact.toLowerCase().replace(/[^a-z0-9]+/g,".")}@exemple.pde`:template.email,recipient:"Camille Lou",case_id:c.id,subject:`${template.subject} · ${c.case_number}`,body:template.body(c,template.note)});if(error)throw error;notice=`Nouveau courrier de ${template.from} pour ${c.case_number}.`;await loadWorkspace();if(page==="mailbox")mailboxView="inbox";render();}catch(e){console.error("Arrivée automatique de courrier impossible",e);}}
function startAutomaticMail(){clearInterval(mailArrivalTimer);clearTimeout(mailArrivalTimeout);clearInterval(autoReplyTimer);if(!session)return;mailArrivalTimeout=setTimeout(()=>automaticMailArrival(),45000);mailArrivalTimer=setInterval(automaticMailArrival,210000);checkScheduledReplies();autoReplyTimer=setInterval(checkScheduledReplies,30000);}
function simulateMailArrival(){automaticMailArrival();}
function ringIntercom(){const arrivals=[{name:"Élise Martin",reason:"Rendez-vous avec la direction · Salle Saphir"},{name:"Madame Dajo",reason:"Demande de nouvelles au sujet de Lorençe"},{name:"Un coursier",reason:"Dépôt d’une enveloppe pour le bureau"}];visitor=arrivals[Math.floor(Math.random()*arrivals.length)];cameraPerson={name:visitor.name,camera:"Portail",at:new Date().toISOString()};notice=`Ding dong… ${visitor.name} sonne à l’entrée.`;render();}
async function answerIntercom(choice){const v=visitor;if(!v)return;const summary=`Appel interphone simulé — accès ${choice==="open"?"accordé":"refusé"}.`;const{error}=await supabase.from("call_logs").insert({created_by:session.user.id,contact:v.name,direction:"inbound",summary,follow_up:"",occurred_at:new Date().toISOString()});if(error)notice="L’appel est terminé, mais n’a pas pu être conservé dans le journal.";else{await loadWorkspace();notice=choice==="open"?`${v.name} est autorisé·e à entrer.`:`Accès refusé à ${v.name}.`;}visitor=null;cameraPerson=null;render();}
function toggleCamera(name){cameraState[name]=!cameraState[name];localStorage.setItem("pde-camera-state",JSON.stringify(cameraState));notice=`Vue ${name} ${cameraState[name]?"activée":"désactivée"}.`;render();}
function simulateCameraDetection(){const views=["Portail","Hall","Couloir nord","Archives"].filter(v=>cameraState[v]);const names=["Une visiteuse","Un coursier","Un visiteur","Un membre de l’équipe"];if(!views.length){notice="Active au moins une caméra avant de simuler une détection.";render();return;}cameraPerson={name:names[Math.floor(Math.random()*names.length)],camera:views[Math.floor(Math.random()*views.length)],at:new Date().toISOString()};notice=`Présence simulée détectée au ${cameraPerson.camera.toLowerCase()}.`;render();}
async function loadWorkspace(){if(!session)return;const results=await Promise.all([supabase.from("cases").select("*").order("updated_at",{ascending:false}),supabase.from("appointments").select("*").order("starts_at",{ascending:true}),supabase.from("call_logs").select("*").order("occurred_at",{ascending:false}),supabase.from("lab_analyses").select("*").order("created_at",{ascending:false}),supabase.from("documents").select("*").order("updated_at",{ascending:false}),supabase.from("mailbox_messages").select("*").order("created_at",{ascending:false})]);const [ca,ap,cl,la,do_,mb]=results;if(ca.error){notice="Impossible de récupérer les dossiers. Vérifie la connexion au cloud.";return;}cases=ca.data||[];appointments=ap.data||[];calls=cl.data||[];analyses=la.data||[];documents=do_.data||[];mailbox=mb.error?[]:(mb.data||[]);}
async function init(){if(!ready){render();return;}const{data}=await supabase.auth.getSession();session=data.session;supabase.auth.onAuthStateChange(async(_event,next)=>{session=next;if(session){await loadWorkspace();startAutomaticMail();}else{clearInterval(mailArrivalTimer);clearTimeout(mailArrivalTimeout);clearInterval(autoReplyTimer);cases=[];appointments=[];calls=[];analyses=[];documents=[];mailbox=[];}render();});if(session){await loadWorkspace();startAutomaticMail();}render();if(session){const channel=supabase.channel("pde-workspace");for(const table of ["cases","case_updates","appointments","call_logs","lab_analyses","documents","mailbox_messages"])channel.on("postgres_changes",{event:"*",schema:"public",table},async()=>{await loadWorkspace();render();});channel.subscribe();}}
init();
